const data = $input.first().json.body || $input.first().json;
const errorType = data.error_type || 'unknown';
const agent = data.agent || 'unknown';
const count = data.count || 1;
const logSnippet = (data.log_snippet || '').substring(0, 300);
const ts = new Date().toISOString();

// Build ticket ID
const date = ts.substring(0, 10).replace(/-/g, '');
const ticketId = `TICKET-${date}-ERR`;

// Build Slack alert
const slackText = `🔴 *Error Escalation — ${count} errors detected*\n\n*Type:* ${errorType}\n*Agent:* ${agent}\n*Ticket:* ${ticketId}\n*Log:* \`\`\`${logSnippet}\`\`\`\n\nOPS: investigate and resolve within SLA.`;

// Build ticket entry for TICKET-TRACKER.md
const ticketEntry = `\n### ${ticketId}\n- **Date:** ${ts}\n- **Severity:** P2\n- **Type:** ${errorType}\n- **Agent:** ${agent}\n- **Count:** ${count} errors\n- **Status:** OPEN\n- **Log:** ${logSnippet}\n- **SLA:** 4h`;

return [{ json: { slackText, ticketEntry, ticketId, channel: 'C0AEV3MDEDD' } }];
